<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class InventoryCountLine extends Model {protected $fillable=['inventory_count_id','inventory_product_id','system_quantity','counted_quantity','difference']; protected $casts=['system_quantity'=>'integer','counted_quantity'=>'integer','difference'=>'integer']; public function count():BelongsTo{return $this->belongsTo(InventoryCount::class,'inventory_count_id');} public function product():BelongsTo{return $this->belongsTo(InventoryProduct::class,'inventory_product_id');}}